mapper.select:


    del_flag = '0'
     AND vehicle_type = #{vehicleType}
     AND vehicle_code LIKE CONCAT('%', #{vehicleCode}, '%')
     AND plate_no LIKE CONCAT('%', #{plateNo}, '%')
     AND vehicle_model LIKE CONCAT('%', #{vehicleModel}, '%')
     AND special_sub_type = #{specialSubType}
     AND operator_name LIKE CONCAT('%', #{operatorName}, '%')
     AND enterprise_id = #{enterpriseId}
     AND enterprise_name LIKE CONCAT('%', #{enterpriseName}, '%')
     AND status = #{status}
     AND date_format(create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')
     AND date_format(create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')

ORDER BY vehicle_type ASC, create_time DESC
